// slack.js


import { useState, useEffect } from 'react';
import {
    Box,
    Button,
    CircularProgress
} from '@mui/material';
import axios from 'axios';

export const HubspotIntegration = ({ user, org, integrationParams, setIntegrationParams }) => {
    const [isConnected, setIsConnected] = useState(false);
    const [isConnecting, setIsConnecting] = useState(false);

    // Opens OAuth flow (backend builds and returns auth_url)
    const handleConnectClick = async () => {
        setIsConnecting(true);
        try {
            const form = new FormData();
            form.append('user_id', user);
            form.append('org_id', org);

            const resp = await axios.post('/integrations/hubspot/authorize', form);
            // server returns a string URL (same pattern used by airtable/notion)
            const authUrl = resp.data;
            // If resp is plain url string, just open it; it might return a location string or full html
            // If the backend returns the URL (like other integrations), it will be a string.
            // We'll open a popup for OAuth.
            const width = 900;
            const height = 700;
            const left = (screen.width / 2) - (width / 2);
            const top = (screen.height / 2) - (height / 2);
            window.open(
                typeof authUrl === 'string' ? authUrl : authUrl?.auth_url || authUrl?.url,
                'hubspot_oauth',
                `menubar=no,toolbar=no,status=no,width=${width},height=${height},top=${top},left=${left}`
            );

            // After popup completes, the backend stores credentials in Redis for retrieval by the frontend
            // The pattern used by other integrations: after callback, user clicks "Check for credentials" or similar.
            setIsConnecting(false);
        } catch (err) {
            console.error('Failed to start HubSpot OAuth', err);
            setIsConnecting(false);
        }
    };

    // Poll for credentials once user has authorized (this is the same pattern the other components use)
    const handleRetrieveCredentials = async () => {
        setIsConnecting(true);
        try {
            const form = new FormData();
            form.append('user_id', user);
            form.append('org_id', org);

            const resp = await axios.post('/integrations/hubspot/credentials', form);
            // The backend returns the credentials JSON object
            const creds = resp.data;
            // Set it in parent form state so DataForm can use it
            setIntegrationParams({ ...integrationParams, credentials: creds, type: 'HubSpot' });
            setIsConnected(true);
        } catch (err) {
            console.error('No HubSpot credentials found yet:', err);
            // leave as not connected
        } finally {
            setIsConnecting(false);
        }
    };

    return (
      <>
        <Box sx={{display: 'flex', alignItems: 'center', gap: 2}}>
            <Box>
                <Button
                    variant="contained"
                    onClick={handleConnectClick}
                    disabled={isConnecting}
                    style={{
                        pointerEvents: isConnected ? 'none' : 'auto',
                        cursor: isConnected ? 'default' : 'pointer',
                        opacity: isConnected ? 1 : undefined
                    }}
                >
                    {isConnected ? 'HubSpot Connected' : isConnecting ? <CircularProgress size={20} /> : 'Connect to HubSpot'}
                </Button>
            </Box>

            <Box>
                <Button
                    variant="outlined"
                    onClick={handleRetrieveCredentials}
                    disabled={isConnecting}
                >
                    {isConnecting ? <CircularProgress size={20} /> : 'Retrieve HubSpot Credentials'}
                </Button>
            </Box>
        </Box>
      </>
    );
};

